---@class UISkillCompoundNode                         
local UISkillCompoundNode = Class("UISkillCompoundNode")

function UISkillCompoundNode:__init()
    self._vo = nil
    self._cb = nil
    self._curQuestId = nil
    self._curTeamIndex = nil
end

function UISkillCompoundNode:__delete()
    self._vo = nil
    self._cb = nil
    self._curQuestId = nil
    self._curTeamIndex = nil
end

function UISkillCompoundNode:Awake()
    SetButtonAction(self.controller.gameObject, Bind(self, self.OnBntSelect))
    --SetButtonAction(self.StatusTopping, Bind(self, self.OnBntCollect))
end

function UISkillCompoundNode:Refresh(data, cb, questId, teamIndex)
    if not data then
        return
    end
    self._vo = data
    self._cb = cb
    self._curQuestId = questId
    self._curTeamIndex = teamIndex

    self:FillSelf()
    self:RefreshSelectActive(false)

    self:FillBase()
end

function UISkillCompoundNode:FillBase()
    CfUtils.FillText(self.TextSkillDesc, self._vo.desc)
end

function UISkillCompoundNode:FillSelf()
    local data = QuestConfMgr:GetInstance():GetMergeSkillData(self._vo.id)
    local isUnlock = (data ~= nil)
    CfUtils.SetActive(self.SratusLock, not isUnlock)
    CfUtils.SetActive(self.SratusUnlock, isUnlock)

    local vo = MaidCoffeeUtils.GetMaidCoffeeCatRollConfigVo(self._vo.catId)
    CfUtils.FillImage(self.ImgCat, vo.picture1)

    CfUtils.SetActive(self.ImgDisabled, not isUnlock)

    local scr = CfUtils.GetLuaScr(self.TextNumber.transform:Find("StarLevel"), "Game.MaidCoffee.MaidCoffeeUIDialog.OverseaManageCatBallStarGroup")
    if isUnlock then
        CfUtils.FillText(self.TextNumber, data.level)
        if checkNumber(data.star) >= MaidCoffeeUtils.CalcCatRollMaxStar() then
            CfUtils.FillImage(self.ImgCat, vo.picture2)
        else
            CfUtils.FillImage(self.ImgCat, vo.picture1)
        end

        if scr then
            scr:FreshUI(data.star)
        end
    else
        local lv, star = self:GetDefaultLvStar()
        if scr then
            scr:FreshUI(star)
        end
    end
    CfUtils.FillText(self.TextName, vo.name)
    CfUtils.FillText(self.TextSkillDesc, vo.desc)

    local curUseId = teamComponent:GetCurSkillCompoundId(self._curQuestId, self._curTeamIndex)
    local isCurUse = checkNumber(self._vo.id) == checkNumber(curUseId)
    CfUtils.SetActive(self.Current, isCurUse)
end

function UISkillCompoundNode:GetDefaultLvStar()
    local t = CfUtils.GetCf(AutoIds.IdSetting4002, "MaidCoffeeCatRollStarVo", true)
    local star = t[1].starId
    local t = CfUtils.GetCf(AutoIds.IdSetting4001, "MaidCoffeeCatRollLevelVo", true)
    local lv = t[1].rankId
    return lv, star
end

--选择
function UISkillCompoundNode:RefreshSelectActive(isTrue)
    CfUtils.SetActive(self.ImgSelect, isTrue)
    if isTrue then
        CfUtils.PlayAnimator(self.controller.gameObject, "Selected")
    else
        CfUtils.PlayAnimator(self.controller.gameObject, "Unselected")
    end
end

function UISkillCompoundNode:RefreshCollectActive(isTrue)
    local status = isTrue and 2 or 1
    CfUtils.SetUISwitchImage(self.StatusTopping, 2)
    CfUtils.SetActive(self.StatusTopping, isTrue)
end

function UISkillCompoundNode:OnBntSelect()
    if not self._cb then 
        return
    end
    self._cb()
end

--收藏
function UISkillCompoundNode:OnBntCollect()
    if not self._collectCb then 
        return
    end
    self._collectCb()
end

function UISkillCompoundNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UISkillCompoundNode





